type Cache struct{ state *State }        // one handle: the exchange is two assignments

func (c *Cache) SwapState(o *Cache) { c.state, o.state = o.state, c.state }

func (c *Cache) Update() error {
    next, err := build()                 // fallible work
    if err != nil {
        return err                       // c.state untouched
    }
    c.state, next = next, c.state        // commit: cannot fail
    return nil
}
